INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", 2, 24001, 0.0, "2030/12/17 14:59:59", 2, 102301, "2020/07/31 12:00:00", "アヤネ", 24, 401, 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", 2, 24002, 0.0, "2030/12/17 14:59:59", 1, 102301, "2020/07/31 12:00:00", "アヤネ", 24, 402, 2.21);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", 2, 24003, 0.0, "2030/12/17 14:59:59", 2, 102301, "2020/07/31 12:00:00", "アヤネ", 24, 403, 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", 1, 24004, 0.0, "2030/12/17 14:59:59", 2, 192201, "2020/07/31 12:00:00", "アサヒ", 24, 701, 1.99);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", 2, 24005, 0.0, "2030/12/17 14:59:59", 1, 192201, "2020/07/31 12:00:00", "アサヒ", 24, 702, 2.21);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", 1, 24006, 0.0, "2030/12/17 14:59:59", 2, 192201, "2020/07/31 12:00:00", "アサヒ", 24, 703, 3.33);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", 2, 24007, 0.0, "2030/12/17 14:59:59", 2, 192301, "2020/07/31 12:00:00", "部員３", 24, 801, 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", 2, 24008, 0.0, "2030/12/17 14:59:59", 1, 192301, "2020/07/31 12:00:00", "部員３", 24, 802, 2.68);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", 2, 24009, 0.0, "2030/12/17 14:59:59", 2, 192301, "2020/07/31 12:00:00", "部員３", 24, 803, 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "やった！", 1, 24010, 0.0, "2030/12/17 14:59:59", 1, 192501, "2020/07/31 12:00:00", "", 24, 501, 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "勝ったよ！", 1, 24011, 0.0, "2030/12/17 14:59:59", 1, 192501, "2020/07/31 12:00:00", "", 24, 502, 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "いい調子！", 1, 24012, 0.0, "2030/12/17 14:59:59", 1, 192501, "2020/07/31 12:00:00", "", 24, 503, 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", 2, 24013, 0.0, "2030/12/17 14:59:59", 6, 113501, "2020/07/31 12:00:00", "ミサト", 24, 111, 5.33);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", 2, 24014, 0.0, "2030/12/17 14:59:59", 1, 113501, "2020/07/31 12:00:00", "ミサト", 24, 112, 6.85);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", 2, 24015, 0.0, "2030/12/17 14:59:59", 1, 113501, "2020/07/31 12:00:00", "ミサト", 24, 113, 3.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", 2, 24016, 0.0, "2030/12/17 14:59:59", 1, 192401, "2020/07/31 12:00:00", "ダイチ", 24, 611, 6.11);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", 2, 24017, 0.0, "2030/12/17 14:59:59", 1, 192401, "2020/07/31 12:00:00", "ダイチ", 24, 612, 6.75);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", 2, 24018, 0.0, "2030/12/17 14:59:59", 2, 192401, "2020/07/31 12:00:00", "ダイチ", 24, 613, 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", 1, 24019, 0.0, "2030/12/17 14:59:59", 2, 113401, "2020/07/31 12:00:00", "ハツネ", 24, 211, 4.52);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", 1, 24020, 0.0, "2030/12/17 14:59:59", 2, 113401, "2020/07/31 12:00:00", "ハツネ", 24, 212, 3.89);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", 2, 24021, 0.0, "2030/12/17 14:59:59", 1, 113401, "2020/07/31 12:00:00", "ハツネ", 24, 213, 13.49);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", 2, 24022, 0.0, "2030/12/17 14:59:59", 1, 106501, "2020/07/31 12:00:00", "カヤ", 24, 311, 3.17);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", 2, 24023, 0.0, "2030/12/17 14:59:59", 1, 106501, "2020/07/31 12:00:00", "カヤ", 24, 312, 4.42);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", 1, 24024, 0.0, "2030/12/17 14:59:59", 6, 106501, "2020/07/31 12:00:00", "カヤ", 24, 313, 2.89);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", 3, 24025, 0.0, "2030/12/17 14:59:59", 4, 102301, "2020/07/31 12:00:00", "アヤネ", 24, 421, 3.71);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", 1, 24026, 0.0, "2030/12/17 14:59:59", 2, 192201, "2020/07/31 12:00:00", "アサヒ", 24, 721, 5.1);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", 3, 24027, 0.0, "2030/12/17 14:59:59", 1, 192301, "2020/07/31 12:00:00", "部員３", 24, 821, 4.34);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "いい勝負だったよ\nまたやろうね", 1, 24028, 0.0, "2030/12/17 14:59:59", 1, 192501, "2020/07/31 12:00:00", "", 24, 521, 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", 2, 24029, -360.0, "2030/12/17 14:59:59", 1, 113501, "2020/07/31 12:00:00", "ミサト", 24, 101, 5.62);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", 2, 24030, -360.0, "2030/12/17 14:59:59", 1, 113501, "2020/07/31 12:00:00", "ミサト", 24, 102, 9.58);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", 2, 24031, -360.0, "2030/12/17 14:59:59", 2, 113501, "2020/07/31 12:00:00", "ミサト", 24, 103, 0.0);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", 1, 24032, -360.0, "2030/12/17 14:59:59", 2, 113501, "2020/07/31 12:00:00", "ミサト", 24, 104, 9.13);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (0.0, 10046, "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", 2, 24033, -360.0, "2030/12/17 14:59:59", 1, 113501, "2020/07/31 12:00:00", "ミサト", 24, 105, 8.27);
